<?php
class Database{private static $pdo=null;public static function connect(){if(self::$pdo===null){$c=require __DIR__.'/../../config/database.php';$dsn="mysql:host={$c['host']};dbname={$c['database']};charset={$c['charset']}";try{self::$pdo=new PDO($dsn,$c['username'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}catch(PDOException $e){die('Database connection failed: '.$e->getMessage());}}return self::$pdo;}}
